// ApplyResult defines model for ApplyResult.
type ApplyResult struct {
	Applied bool `json:"applied"`

	// Dn The entry's DN after the change, which differs for a rename.
	Dn   string  `json:"dn"`
	Ldif *string `json:"ldif,omitempty"`

	// Note Present when the change was accepted but Alder could not confirm
	// where the entry ended up.
	Note *string `json:"note,omitempty"`

	// Recovery The recovery bundle, when one was asked for. Added in 1.9.
	Recovery *json.RawMessage `json:"recovery,omitempty"`

	// StoredDn Where the entry actually came to rest, when that is not the DN the
	// change was addressed to.
	//
	// A directory may store an added entry under a different name: where
	// an entry's position among its siblings forms part of that name, the
	// server assigns the position and rewrites the RDN. Reporting the
	// requested DN in that case sends the caller to an entry that is not
	// there.
	StoredDn *string `json:"storedDn,omitempty"`
	Summary  *string `json:"summary,omitempty"`
}

// AttributeComparison defines model for AttributeComparison.
type AttributeComparison struct {
	Left ComparedSide `json:"left"`

	// Name The attribute description, options included. `userCertificate;binary`
	// and `userCertificate` are two rows, not one.
	Name  string       `json:"name"`
	Right ComparedSide `json:"right"`

	// Status `withheld` means both entries hold the attribute and it was not
	// compared, because it is sensitive. It is a status of its own rather
	// than `same` with a flag beside it: a client reading only this field
	// must not be able to conclude that two passwords match.
	//
	// `undetermined` means the access rules stopped the comparison. The
	// attribute is on one side and was not returned for the other, and
	// asking the server directly said the bind may not look rather than
	// that the entry lacks it. Reporting that as `leftOnly` would be a
	// statement about the directory that this session has no basis for.
	// The side that could not be read carries `denied`.
	Status    AttributeComparisonStatus `json:"status"`
	Truncated *bool                     `json:"truncated,omitempty"`

	// Values Absent for a withheld attribute.
	Values *[]ValueComparison `json:"values,omitempty"`

	// Withheld Sensitive, so no value crosses the wire from either side. Presence
	// is still reported on each side, because `/entry` already says whether
	// a password is set. Equality is not: reporting whether two entries
	// hold the same password hash would be an oracle about password
	// material the product offers nowhere else.
	Withheld *bool `json:"withheld,omitempty"`
}

// AttributeComparisonStatus `withheld` means both entries hold the attribute and it was not
// compared, because it is sensitive. It is a status of its own rather
// than `same` with a flag beside it: a client reading only this field
// must not be able to conclude that two passwords match.
//
// `undetermined` means the access rules stopped the comparison. The
// attribute is on one side and was not returned for the other, and
// asking the server directly said the bind may not look rather than
// that the entry lacks it. Reporting that as `leftOnly` would be a
// statement about the directory that this session has no basis for.
// The side that could not be read carries `denied`.
type AttributeComparisonStatus string

